#include <array>
#include <iostream>
#include <numeric>
int main() {
    const std::array<int, 3> latency_ms{10, 10, 10};
    const int wall_ms = 10; // Supplied overlapping interval, not measured.
    const int summed_ms = std::accumulate(latency_ms.begin(), latency_ms.end(), 0);
    std::cout << "mean latency=" << summed_ms / latency_ms.size() << "ms\n";
    std::cout << "wall throughput=" << latency_ms.size() * 1000 / wall_ms << "/s\n";
    std::cout << "wrong serial rate=" << latency_ms.size() * 1000 / summed_ms << "/s\n";
}

#include <algorithm>
#include <cmath>
#include <iostream>
#include <numeric>
#include <vector>
int main() {
    std::vector<int> milliseconds{1, 1, 1, 1, 1, 1, 1, 1, 1, 91};
    const int total = std::accumulate(milliseconds.begin(), milliseconds.end(), 0);
    std::sort(milliseconds.begin(), milliseconds.end());
    const auto rank = static_cast<std::size_t>(std::ceil(0.95 * milliseconds.size()));
    std::cout << "mean=" << total / milliseconds.size()
              << " median=" << milliseconds[4]
              << " nearest-rank-p95=" << milliseconds[rank - 1] << "ms\n";
}
